import numpy as np
from collections import deque

def transform(inp):
    g = inp.copy()
    H,W = g.shape
    walls = g==1
    # reachable from border avoiding walls
    reach = np.zeros_like(walls)
    dq = deque()
    for r in range(H):
        for c in (0,W-1):
            if not walls[r,c] and not reach[r,c]: reach[r,c]=True; dq.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if not walls[r,c] and not reach[r,c]: reach[r,c]=True; dq.append((r,c))
    while dq:
        r,c = dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc = r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not walls[nr,nc] and not reach[nr,nc]:
                reach[nr,nc]=True; dq.append((nr,nc))
    inside = ~walls & ~reach
    if not inside.any():
        return g  # open figure: unchanged
    # chebyshev distance 1 from any wall
    near = np.zeros_like(walls)
    wr,wc = np.nonzero(walls)
    for dr in (-1,0,1):
        for dc in (-1,0,1):
            if dr==0 and dc==0: continue
            rr = wr+dr; cc = wc+dc
            ok = (rr>=0)&(rr<H)&(cc>=0)&(cc<W)
            near[rr[ok],cc[ok]] = True
    out = g.copy()
    out[~walls & near & inside] = 3
    out[~walls & near & ~inside] = 2
    return out

for name,(ii,oo) in enumerate([(i1,o1),(i2,o2),(i3,o3)]):
    pred = transform(ii)
    print(f"demo{name+1} match:", np.array_equal(pred, oo))
    if not np.array_equal(pred,oo):
        d = np.argwhere(pred!=oo)
        print([(tuple(x), int(ii[x[0],x[1]]), int(pred[x[0],x[1]]), int(oo[x[0],x[1]])) for x in d][:20])

def transform2(inp):
    g = inp.copy(); H,W = g.shape
    walls = g==1
    # connected components of walls (8-conn? use 4-conn first)
    from collections import deque
    lab = -np.ones((H,W),int)
    comps=[]
    for r in range(H):
        for c in range(W):
            if walls[r,c] and lab[r,c]<0:
                cid=len(comps); q=deque([(r,c)]); lab[r,c]=cid; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=a+dr,b+dc
                        if 0<=nr<H and 0<=nc<W and walls[nr,nc] and lab[nr,nc]<0:
                            lab[nr,nc]=cid; q.append((nr,nc))
                comps.append(cells)
    out = g.copy()
    for cells in comps:
        cw = np.zeros((H,W),bool)
        for a,b in cells: cw[a,b]=True
        # flood from border avoiding this component's walls only
        reach = np.zeros((H,W),bool); dq=deque()
        for r in range(H):
            for c in (0,W-1):
                if not cw[r,c] and not reach[r,c]: reach[r,c]=True; dq.append((r,c))
        for c in range(W):
            for r in (0,H-1):
                if not cw[r,c] and not reach[r,c]: reach[r,c]=True; dq.append((r,c))
        while dq:
            a,b=dq.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=a+dr,b+dc
                if 0<=nr<H and 0<=nc<W and not cw[nr,nc] and not reach[nr,nc]:
                    reach[nr,nc]=True; dq.append((nr,nc))
        inside = ~cw & ~reach
        if not inside.any(): continue  # open figure: unchanged
        # cells chebyshev-1 from this component's walls
        near = np.zeros((H,W),bool)
        rr_,cc_ = zip(*cells)
        rr_=np.array(rr_); cc_=np.array(cc_)
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if dr==0 and dc==0: continue
                R=rr_+dr; C=cc_+dc
                ok=(R>=0)&(R<H)&(C>=0)&(C<W)
                near[R[ok],C[ok]]=True
        sel_in = near & inside
        sel_out = near & ~cw & ~inside
        out[sel_in]=3; out[sel_out]=2
    return out

for name,(ii,oo) in enumerate([(i1,o1),(i2,o2),(i3,o3)]):
    pred = transform2(ii)
    print(f"demo{name+1} match:", np.array_equal(pred, oo))
    if not np.array_equal(pred,oo):
        d=np.argwhere(pred!=oo)
        print([(tuple(x),int(ii[x[0],x[1]]),int(pred[x[0],x[1]]),int(oo[x[0],x[1]])) for x in d][:20])
